"""Datos de la línea de tiempo «Pablo, apóstol de las naciones».

Fuente única: de aquí salen estudios/lineas/pablo.html (scripts/lineas_generar.py pablo) y
estudios/lineas/pablo/mapa/atlas.json. Cronología anclada en la inscripción de Delfos (Galión, 51–52 e. c.).
Los textos bíblicos son traducción propia desde el griego (SBLGNT) y el hebreo (Códice de Leningrado); el
texto original se lee de los archivos de la app (textos.py), no se transcribe a mano.
"""
import json, sys
from pathlib import Path
AQUI = Path(__file__).resolve().parent
sys.path.insert(0, str(AQUI))
import textos as T
from atlas_datos import ATLAS

# ---------------------------------------------------------------------------------------------
# Pasajes bíblicos: clave → (cita, era, traducción propia). El original se toma de textos.py.
# ---------------------------------------------------------------------------------------------
P = {
 "1co15_8": ("1 Co 15:8–10", 0, "⁸ Y al último de todos, como a uno nacido fuera de tiempo, se me apareció también a mí. ⁹ Porque yo soy el más pequeño de los apóstoles, que no soy digno de ser llamado apóstol, porque perseguí a la iglesia de Dios. ¹⁰ Pero por la gracia de Dios soy lo que soy, y su gracia para conmigo no resultó vana; al contrario, trabajé más que todos ellos; pero no yo, sino la gracia de Dios conmigo."),
 "2p3_15": ("2 P 3:15–16", 9, "¹⁵ Y tengan por salvación la paciencia de nuestro Señor, como también nuestro amado hermano Pablo les escribió según la sabiduría que le fue dada, ¹⁶ como en todas las cartas, hablando en ellas de estas cosas; en las que hay algunas difíciles de entender, que los ignorantes e inestables tuercen, como también las otras Escrituras, para su propia perdición."),
 "ga1_18": ("Gá 1:18–19", 2, "¹⁸ Después, pasados tres años, subí a Jerusalén para conocer a Cefas, y permanecí con él quince días; ¹⁹ pero no vi a ningún otro de los apóstoles, sino a Jacobo, el hermano del Señor."),
 "ga2_1": ("Gá 2:1–2", 4, "¹ Después, pasados catorce años, subí otra vez a Jerusalén con Bernabé, llevando también conmigo a Tito. ² Subí por una revelación, y les expuse el evangelio que predico entre las naciones, pero en privado a los de reputación, no fuera que corriese o hubiese corrido en vano."),
 "hch22_3": ("Hch 22:3", 0, "Yo soy un hombre judío, nacido en Tarso de Cilicia, pero criado en esta ciudad, instruido a los pies de Gamaliel en la exactitud de la ley de los padres, celoso de Dios como todos ustedes lo son hoy."),
 "hch22_28": ("Hch 22:27–28", 0, "²⁷ Acercándose el tribuno le dijo: «Dime, ¿eres tú romano?». Él dijo: «Sí». ²⁸ Respondió el tribuno: «Yo adquirí esta ciudadanía por una gran suma». Y Pablo dijo: «Pero yo la tengo de nacimiento»."),
 "fil3_5": ("Fil 3:4–6", 0, "⁴ Aunque yo tengo también de qué confiar en la carne. Si alguno piensa que puede confiar en la carne, yo más: ⁵ circuncidado al octavo día, del linaje de Israel, de la tribu de Benjamín, hebreo de hebreos; en cuanto a la ley, fariseo; ⁶ en cuanto a celo, perseguidor de la iglesia; en cuanto a la justicia que es por la ley, irreprensible."),
 "hch7_58": ("Hch 7:58–8:1", 1, "⁵⁸ Y echándolo fuera de la ciudad, lo apedreaban; y los testigos dejaron sus mantos a los pies de un joven llamado Saulo. ⁵⁹ Y apedreaban a Esteban, que invocaba y decía: «Señor Jesús, recibe mi espíritu». ⁶⁰ Puesto de rodillas, clamó a gran voz: «Señor, no les tomes en cuenta este pecado». Y dicho esto, durmió. ¹ Y Saulo consentía en su muerte."),
 "hch8_1": ("Hch 8:1", 1, "Y Saulo consentía en su muerte. En aquel día hubo una gran persecución contra la iglesia que estaba en Jerusalén, y todos, excepto los apóstoles, fueron dispersados por las regiones de Judea y de Samaria."),
 "hch8_3": ("Hch 8:3", 1, "Y Saulo asolaba la iglesia: entrando casa por casa, arrastraba a hombres y mujeres y los entregaba a la cárcel."),
 "hch9_1": ("Hch 9:1–2", 1, "¹ Saulo, respirando aún amenazas y muerte contra los discípulos del Señor, se presentó al sumo sacerdote ² y le pidió cartas para las sinagogas de Damasco, a fin de que, si hallaba algunos del Camino, hombres o mujeres, los trajera presos a Jerusalén."),
 "ga1_13": ("Gá 1:13–14", 1, "¹³ Porque ya oyeron de mi conducta de antes en el judaísmo: que perseguía sobremanera a la iglesia de Dios y la asolaba, ¹⁴ y adelantaba en el judaísmo más que muchos de mi edad en mi nación, siendo mucho más celoso de las tradiciones de mis padres."),
 "hch9_3": ("Hch 9:3–6", 1, "³ Y yendo por el camino, sucedió que al acercarse a Damasco, de repente lo rodeó una luz del cielo; ⁴ y cayendo en tierra oyó una voz que le decía: «Saulo, Saulo, ¿por qué me persigues?». ⁵ Dijo: «¿Quién eres, Señor?». Y él: «Yo soy Jesús, a quien tú persigues; ⁶ pero levántate y entra en la ciudad, y se te dirá lo que debes hacer»."),
 "hch26_14": ("Hch 26:14", 1, "Y habiendo caído todos nosotros a tierra, oí una voz que me decía en lengua hebrea: «Saulo, Saulo, ¿por qué me persigues? Dura cosa te es dar coces contra el aguijón»."),
 "ga1_15": ("Gá 1:15–16", 1, "¹⁵ Pero cuando le agradó a Dios, que me apartó desde el vientre de mi madre y me llamó por su gracia, ¹⁶ revelar a su Hijo en mí para que yo lo anunciara entre las naciones, no consulté en seguida con carne y sangre."),
 "hch9_15": ("Hch 9:15–16", 1, "¹⁵ El Señor le dijo: «Ve, porque instrumento escogido me es éste, para llevar mi nombre ante las naciones, y reyes, y los hijos de Israel; ¹⁶ porque yo le mostraré cuánto le es necesario padecer por mi nombre»."),
 "hch9_17": ("Hch 9:17–18", 1, "¹⁷ Fue Ananías y entró en la casa, y poniendo sobre él las manos dijo: «Hermano Saulo, el Señor Jesús, que se te apareció en el camino por donde venías, me ha enviado para que recobres la vista y seas lleno del Espíritu Santo». ¹⁸ Y al momento cayeron de sus ojos como escamas, y recobró la vista; se levantó y fue bautizado."),
 "ga1_17": ("Gá 1:17", 1, "Ni subí a Jerusalén a los que eran apóstoles antes que yo, sino que fui a Arabia, y volví de nuevo a Damasco."),
 "hch9_20": ("Hch 9:20–22", 1, "²⁰ Y en seguida predicaba a Jesús en las sinagogas: que éste es el Hijo de Dios. ²¹ Todos los que lo oían estaban atónitos y decían: «¿No es éste el que asolaba en Jerusalén a los que invocaban este nombre, y a eso vino acá, para llevarlos presos ante los sumos sacerdotes?». ²² Pero Saulo se fortalecía más y más, y confundía a los judíos que vivían en Damasco, demostrando que éste es el Mesías."),
 "hch9_23": ("Hch 9:23–25", 1, "²³ Pasados muchos días, los judíos resolvieron en consejo matarlo; ²⁴ pero sus asechanzas llegaron a conocimiento de Saulo. Y ellos vigilaban también las puertas de día y de noche para matarlo. ²⁵ Entonces sus discípulos, tomándolo de noche, lo bajaron por el muro, descolgándolo en una canasta."),
 "2co11_32": ("2 Co 11:32–33", 1, "³² En Damasco, el etnarca del rey Aretas guardaba la ciudad de los damascenos para prenderme; ³³ y fui descolgado del muro en un canasto por una ventana, y escapé de sus manos."),
 "hch9_26": ("Hch 9:26–27", 2, "²⁶ Cuando llegó a Jerusalén, trataba de juntarse con los discípulos; pero todos le tenían miedo, no creyendo que fuera discípulo. ²⁷ Entonces Bernabé, tomándolo, lo trajo a los apóstoles, y les contó cómo en el camino había visto al Señor, que le había hablado, y cómo en Damasco había hablado con valentía en el nombre de Jesús."),
 "hch22_17": ("Hch 22:17–18.21", 2, "¹⁷ Y me aconteció, vuelto a Jerusalén, que orando en el templo me sobrevino un éxtasis ¹⁸ y lo vi a él, que me decía: «Date prisa y sal pronto de Jerusalén, porque no recibirán tu testimonio acerca de mí». ²¹ Y me dijo: «Ve, porque yo te enviaré lejos, a las naciones»."),
 "hch9_30": ("Hch 9:30–31", 2, "³⁰ Cuando supieron esto los hermanos, lo llevaron a Cesarea y lo enviaron a Tarso. ³¹ Entonces la iglesia tenía paz por toda Judea, Galilea y Samaria; se edificaba y andaba en el temor del Señor, y se acrecentaba con el consuelo del Espíritu Santo."),
 "ga1_21": ("Gá 1:21–24", 2, "²¹ Después fui a las regiones de Siria y de Cilicia; ²² y no era conocido de vista por las iglesias de Judea que están en Cristo; ²³ solamente oían decir: «El que antes nos perseguía ahora predica la fe que en otro tiempo asolaba». ²⁴ Y glorificaban a Dios en mí."),
 "2co12_2": ("2 Co 12:2–4", 2, "² Conozco a un hombre en Cristo que hace catorce años —si en el cuerpo no lo sé, si fuera del cuerpo no lo sé, Dios lo sabe— fue arrebatado hasta el tercer cielo. ³ Y conozco a este hombre —si en el cuerpo o fuera del cuerpo, no lo sé; Dios lo sabe— ⁴ que fue arrebatado al paraíso y oyó palabras inefables que no le es dado al hombre expresar."),
 "hch11_25": ("Hch 11:25–26", 2, "²⁵ Después fue Bernabé a Tarso para buscar a Saulo, ²⁶ y hallándolo lo trajo a Antioquía. Y sucedió que todo un año se congregaron con la iglesia y enseñaron a mucha gente; y a los discípulos se les llamó cristianos por primera vez en Antioquía."),
 "hch11_28": ("Hch 11:28–30", 2, "²⁸ Y levantándose uno de ellos, llamado Agabo, daba a entender por el Espíritu que vendría una gran hambre en toda la tierra habitada; la cual sucedió en tiempo de Claudio. ²⁹ Entonces los discípulos, cada uno conforme a lo que tenía, determinaron enviar socorro a los hermanos que habitaban en Judea; ³⁰ lo cual hicieron, enviándolo a los ancianos por mano de Bernabé y de Saulo."),
 "ga2_10": ("Gá 2:9–10", 2, "⁹ Y reconociendo la gracia que me había sido dada, Jacobo, Cefas y Juan, que eran considerados columnas, nos dieron a mí y a Bernabé la mano derecha de comunión, para que nosotros fuéramos a las naciones y ellos a la circuncisión; ¹⁰ solamente que nos acordáramos de los pobres, lo mismo que yo procuré con diligencia hacer."),
 "hch13_2": ("Hch 13:2–3", 3, "² Mientras servían al Señor y ayunaban, dijo el Espíritu Santo: «Apártenme a Bernabé y a Saulo para la obra a la que los he llamado». ³ Entonces, habiendo ayunado y orado, les impusieron las manos y los despidieron."),
 "hch13_6": ("Hch 13:6–8", 3, "⁶ Y habiendo atravesado toda la isla hasta Pafos, hallaron a un hombre mago, falso profeta, judío, llamado Barjesús, ⁷ que estaba con el procónsul Sergio Paulo, varón prudente. Éste, llamando a Bernabé y a Saulo, deseaba oír la palabra de Dios. ⁸ Pero les resistía Elimas, el mago (pues así se traduce su nombre), procurando apartar de la fe al procónsul."),
 "hch13_9": ("Hch 13:9–12", 3, "⁹ Entonces Saulo, que también es Pablo, lleno del Espíritu Santo, fijando en él los ojos ¹⁰ dijo: «¡Oh, lleno de todo engaño y de toda maldad, hijo del diablo, enemigo de toda justicia! ¿No cesarás de trastornar los caminos rectos del Señor? ¹¹ Ahora, pues, he aquí la mano del Señor está contra ti, y serás ciego, y no verás el sol por un tiempo». Al instante cayeron sobre él oscuridad y tinieblas, y andando alrededor buscaba quien lo condujera de la mano. ¹² Entonces el procónsul, viendo lo que había sucedido, creyó, maravillado de la doctrina del Señor."),
 "hch13_13": ("Hch 13:13–14", 3, "¹³ Habiendo zarpado de Pafos, Pablo y sus compañeros llegaron a Perge de Panfilia; pero Juan, apartándose de ellos, volvió a Jerusalén. ¹⁴ Ellos, pasando de Perge, llegaron a Antioquía de Pisidia; y entraron en la sinagoga el día del sábado y se sentaron."),
 "ga4_13": ("Gá 4:13–14", 3, "¹³ Saben que a causa de una debilidad de la carne les anuncié el evangelio al principio; ¹⁴ y no desecharon ni despreciaron lo que en mi carne era una prueba para ustedes, sino que me recibieron como a un ángel de Dios, como a Cristo Jesús."),
 "hch13_38": ("Hch 13:38–39", 3, "³⁸ Sépanlo, pues, varones hermanos: que por medio de éste se les anuncia el perdón de pecados, ³⁹ y de todo aquello de que por la ley de Moisés no pudieron ser justificados, en él es justificado todo el que cree."),
 "hch13_47": ("Hch 13:46–47", 3, "⁴⁶ Entonces Pablo y Bernabé, hablando con valentía, dijeron: «A ustedes era necesario que se les hablara primero la palabra de Dios; pero puesto que la rechazan y no se juzgan dignos de la vida eterna, he aquí nos volvemos a las naciones. ⁴⁷ Porque así nos ha mandado el Señor: Te he puesto por luz de las naciones, para que seas salvación hasta el extremo de la tierra»."),
 "hch14_11": ("Hch 14:11–13", 3, "¹¹ Las multitudes, viendo lo que Pablo había hecho, alzaron la voz diciendo en lengua licaónica: «¡Dioses semejantes a hombres han descendido a nosotros!». ¹² Y a Bernabé lo llamaban Zeus, y a Pablo, Hermes, porque éste era el que llevaba la palabra. ¹³ Y el sacerdote de Zeus, cuyo templo estaba frente a la ciudad, trajo toros y guirnaldas a las puertas, y con la multitud quería ofrecer sacrificio."),
 "hch14_19": ("Hch 14:19–20", 3, "¹⁹ Pero vinieron unos judíos de Antioquía y de Iconio que persuadieron a la multitud, y habiendo apedreado a Pablo, lo arrastraron fuera de la ciudad pensando que estaba muerto. ²⁰ Pero rodeándolo los discípulos, se levantó y entró en la ciudad; y al día siguiente salió con Bernabé para Derbe."),
 "2ti3_11": ("2 Ti 3:10–11", 3, "¹⁰ Pero tú has seguido mi enseñanza, conducta, propósito, fe, paciencia, amor, perseverancia, ¹¹ persecuciones, padecimientos, como los que me sobrevinieron en Antioquía, en Iconio, en Listra; persecuciones que he sufrido, y de todas me libró el Señor."),
 "hch14_22": ("Hch 14:21–23", 3, "²¹ Después de anunciar el evangelio a aquella ciudad y de hacer muchos discípulos, volvieron a Listra, a Iconio y a Antioquía, ²² confirmando los ánimos de los discípulos, exhortándolos a permanecer en la fe, y diciéndoles que es necesario que a través de muchas tribulaciones entremos en el reino de Dios. ²³ Y habiéndoles designado ancianos en cada iglesia, orando con ayunos, los encomendaron al Señor en quien habían creído."),
 "hch14_27": ("Hch 14:26–27", 3, "²⁶ De allí navegaron a Antioquía, desde donde habían sido encomendados a la gracia de Dios para la obra que habían cumplido. ²⁷ Y habiendo llegado, reunieron a la iglesia y refirieron cuán grandes cosas había hecho Dios con ellos, y cómo había abierto a las naciones la puerta de la fe."),
 "ga1_6": ("Gá 1:6–7", 4, "⁶ Me maravillo de que tan pronto se hayan pasado, del que los llamó por la gracia de Cristo, a un evangelio diferente, ⁷ que no es otro, sino que hay algunos que los perturban y quieren pervertir el evangelio de Cristo."),
 "ga2_16": ("Gá 2:15–16", 4, "¹⁵ Nosotros, judíos de nacimiento y no pecadores de entre las naciones, ¹⁶ sabiendo que el hombre no es justificado por obras de la ley sino por la fe de Jesucristo, también nosotros hemos creído en Cristo Jesús, para ser justificados por la fe de Cristo y no por obras de la ley, porque por obras de la ley nadie será justificado."),
 "ga3_28": ("Gá 3:28", 4, "No hay judío ni griego; no hay esclavo ni libre; no hay varón y mujer; porque todos ustedes son uno en Cristo Jesús."),
 "hch15_11": ("Hch 15:10–11", 4, "¹⁰ Ahora, pues, ¿por qué tientan a Dios poniendo sobre la cerviz de los discípulos un yugo que ni nuestros padres ni nosotros hemos podido llevar? ¹¹ Antes creemos que por la gracia del Señor Jesús seremos salvos, de igual modo que ellos."),
 "hch15_28": ("Hch 15:28–29", 4, "²⁸ Porque ha parecido bien al Espíritu Santo y a nosotros no imponerles ninguna carga más que estas cosas necesarias: ²⁹ que se abstengan de lo sacrificado a los ídolos, de sangre, de ahogado y de fornicación; si se guardan de estas cosas, harán bien. Que les vaya bien."),
 "ga2_9": ("Gá 2:7–9", 4, "⁷ Al contrario, viendo que me había sido encomendado el evangelio de la incircuncisión, como a Pedro el de la circuncisión ⁸ —pues el que actuó en Pedro para el apostolado de la circuncisión actuó también en mí para con las naciones—, ⁹ y reconociendo la gracia que me había sido dada, Jacobo, Cefas y Juan, considerados columnas, nos dieron a mí y a Bernabé la mano derecha de comunión."),
 "ga2_11": ("Gá 2:11–13", 4, "¹¹ Pero cuando Cefas vino a Antioquía, le resistí cara a cara, porque era digno de condena. ¹² Pues antes de que vinieran algunos de parte de Jacobo, comía con los de las naciones; pero cuando vinieron, se retraía y se apartaba, temiendo a los de la circuncisión. ¹³ Y en su simulación participaban también los otros judíos, de modo que hasta Bernabé fue arrastrado por la hipocresía de ellos."),
 "ga2_14": ("Gá 2:14", 4, "Pero cuando vi que no andaban rectamente conforme a la verdad del evangelio, dije a Cefas delante de todos: «Si tú, siendo judío, vives como los de las naciones y no como judío, ¿por qué obligas a los de las naciones a judaizar?»."),
 "hch15_37": ("Hch 15:37–40", 5, "³⁷ Bernabé quería llevar consigo a Juan, el llamado Marcos; ³⁸ pero a Pablo le parecía bien no llevar consigo al que se había apartado de ellos desde Panfilia y no había ido con ellos a la obra. ³⁹ Y hubo tal desacuerdo entre ellos que se separaron el uno del otro: Bernabé, tomando a Marcos, navegó a Chipre, ⁴⁰ y Pablo, escogiendo a Silas, salió encomendado por los hermanos a la gracia del Señor."),
 "2ti4_11": ("2 Ti 4:11", 5, "Solo Lucas está conmigo. Toma a Marcos y tráelo contigo, porque me es útil para el ministerio."),
 "hch16_1": ("Hch 16:1–3", 5, "¹ Llegó también a Derbe y a Listra. Y he aquí había allí un discípulo llamado Timoteo, hijo de una mujer judía creyente, pero de padre griego, ² del que daban buen testimonio los hermanos de Listra y de Iconio. ³ Quiso Pablo que éste fuera con él, y tomándolo lo circuncidó por causa de los judíos que había en aquellos lugares, porque todos sabían que su padre era griego."),
 "2ti1_5": ("2 Ti 1:5", 5, "Trayendo a la memoria la fe no fingida que hay en ti, la cual habitó primero en tu abuela Loida y en tu madre Eunice, y estoy seguro de que también en ti."),
 "1co9_20": ("1 Co 9:20–22", 5, "²⁰ Me he hecho a los judíos como judío, para ganar a los judíos; a los que están bajo la ley, como bajo la ley —aunque yo no esté bajo la ley—, para ganar a los que están bajo la ley; ²¹ a los que están sin ley, como sin ley —no estando yo sin ley de Dios, sino bajo la ley de Cristo—, para ganar a los que están sin ley. ²² Me he hecho débil a los débiles, para ganar a los débiles; a todos me he hecho todo, para que de todos modos salve a algunos."),
 "hch16_6": ("Hch 16:6–8", 5, "⁶ Atravesaron Frigia y la región de Galacia, impedidos por el Espíritu Santo de hablar la palabra en Asia; ⁷ y cuando llegaron a Misia intentaron ir a Bitinia, pero el Espíritu de Jesús no se lo permitió. ⁸ Y pasando junto a Misia, descendieron a Troas."),
 "hch16_9": ("Hch 16:9–10", 5, "⁹ Y se le mostró a Pablo una visión de noche: un varón macedonio estaba de pie, rogándole y diciendo: «Pasa a Macedonia y ayúdanos». ¹⁰ Cuando vio la visión, en seguida procuramos partir para Macedonia, dando por cierto que Dios nos llamaba para anunciarles el evangelio."),
 "col4_14": ("Col 4:14", 5, "Los saluda Lucas, el médico amado, y Demas."),
 "hch16_14": ("Hch 16:14–15", 5, "¹⁴ Entonces una mujer llamada Lidia, vendedora de púrpura, de la ciudad de Tiatira, que adoraba a Dios, estaba oyendo; y el Señor abrió su corazón para que estuviera atenta a lo que Pablo decía. ¹⁵ Cuando fue bautizada, con su familia, nos rogó diciendo: «Si han juzgado que soy fiel al Señor, entren en mi casa y quédense». Y nos obligó a quedarnos."),
 "hch16_30": ("Hch 16:29–31", 5, "²⁹ Él entonces, pidiendo luz, se precipitó adentro y, temblando, se postró ante Pablo y Silas; ³⁰ y sacándolos fuera dijo: «Señores, ¿qué debo hacer para ser salvo?». ³¹ Ellos dijeron: «Cree en el Señor Jesús, y serás salvo tú y tu casa»."),
 "fil4_15": ("Fil 4:15–16", 5, "¹⁵ Y saben también ustedes, filipenses, que al principio del evangelio, cuando partí de Macedonia, ninguna iglesia participó conmigo en razón de dar y recibir, sino ustedes solos; ¹⁶ pues aun a Tesalónica me enviaron una y otra vez para mis necesidades."),
 "hch17_3": ("Hch 17:2–3", 5, "² Y Pablo, como acostumbraba, fue a ellos, y por tres sábados discutió con ellos desde las Escrituras, ³ explicando y demostrando que era necesario que el Mesías padeciera y resucitara de los muertos, y que «éste es el Mesías, Jesús, a quien yo les anuncio»."),
 "hch17_6": ("Hch 17:6–7", 5, "⁶ Al no hallarlos, arrastraron a Jasón y a algunos hermanos ante los politarcas, gritando: «Éstos que han trastornado el mundo entero han venido también acá; ⁷ Jasón los ha recibido, y todos ellos actúan contra los decretos del César, diciendo que hay otro rey, Jesús»."),
 "hch17_11": ("Hch 17:11", 5, "Éstos eran más nobles que los de Tesalónica: recibieron la palabra con toda disposición, examinando cada día las Escrituras para ver si estas cosas eran así."),
 "hch17_23": ("Hch 17:22–23", 5, "²² Pablo, de pie en medio del Areópago, dijo: «Varones atenienses, en todo observo que son muy religiosos; ²³ porque pasando y mirando sus santuarios, hallé también un altar en el que estaba escrito: AL DIOS DESCONOCIDO. Al que ustedes adoran sin conocer, a ése les anuncio yo»."),
 "hch17_28": ("Hch 17:28–31", 5, "²⁸ Porque en él vivimos, nos movemos y somos; como algunos de sus propios poetas han dicho: «Porque linaje suyo somos». ²⁹ Siendo, pues, linaje de Dios, no debemos pensar que la divinidad sea semejante a oro, plata o piedra, escultura de arte y de imaginación de hombre. ³⁰ Dios, pues, pasando por alto los tiempos de la ignorancia, ahora manda a todos los hombres en todo lugar que se arrepientan, ³¹ por cuanto ha fijado un día en que juzgará al mundo con justicia por medio de un varón que designó, dando fe a todos con haberlo resucitado de los muertos."),
 "hch18_2": ("Hch 18:2–3", 5, "² Halló a un judío llamado Aquila, natural del Ponto, recién llegado de Italia con Priscila su mujer, porque Claudio había mandado que todos los judíos salieran de Roma. Fue a ellos ³ y, como era del mismo oficio, se quedó con ellos y trabajaban juntos, pues el oficio de ellos era hacer tiendas."),
 "hch18_9": ("Hch 18:9–11", 5, "⁹ Y el Señor dijo a Pablo de noche, en visión: «No temas, sino habla y no calles, ¹⁰ porque yo estoy contigo, y nadie pondrá la mano sobre ti para hacerte mal, porque tengo mucho pueblo en esta ciudad». ¹¹ Y se detuvo allí un año y seis meses, enseñando entre ellos la palabra de Dios."),
 "1ts1_9": ("1 Ts 1:9–10", 5, "⁹ Porque ellos mismos cuentan de nosotros la manera en que nos recibieron, y cómo se convirtieron de los ídolos a Dios para servir al Dios vivo y verdadero, ¹⁰ y esperar de los cielos a su Hijo, al cual resucitó de los muertos, a Jesús, quien nos libra de la ira venidera."),
 "1ts4_16": ("1 Ts 4:16–17", 5, "¹⁶ Porque el Señor mismo, con voz de mando, con voz de arcángel y con trompeta de Dios, descenderá del cielo; y los muertos en Cristo resucitarán primero. ¹⁷ Luego nosotros, los que vivimos, los que quedamos, seremos arrebatados juntamente con ellos en las nubes al encuentro del Señor en el aire, y así estaremos siempre con el Señor."),
 "2ts3_10": ("2 Ts 3:10", 5, "Porque también cuando estábamos con ustedes les ordenábamos esto: si alguno no quiere trabajar, que tampoco coma."),
 "hch18_12": ("Hch 18:12–16", 5, "¹² Pero siendo Galión procónsul de Acaya, los judíos se levantaron de común acuerdo contra Pablo y lo llevaron al tribunal, ¹³ diciendo: «Éste persuade a los hombres a honrar a Dios contra la ley». ¹⁴ Y al comenzar Pablo a hablar, Galión dijo a los judíos: «Si fuera algún agravio o crimen enorme, oh judíos, conforme a derecho los toleraría; ¹⁵ pero si son cuestiones de palabras, de nombres y de la ley de ustedes, véanlo ustedes; yo no quiero ser juez de estas cosas». ¹⁶ Y los echó del tribunal."),
 "hch18_18": ("Hch 18:18", 5, "Pablo, habiéndose detenido aún muchos días, se despidió de los hermanos y navegó a Siria, y con él Priscila y Aquila, habiéndose rapado la cabeza en Cencrea, porque tenía un voto."),
 "ro16_1": ("Ro 16:1–2", 5, "¹ Les recomiendo a nuestra hermana Febe, que es diaconisa de la iglesia en Cencrea, ² para que la reciban en el Señor como es digno de los santos y la ayuden en cualquier cosa en que necesite de ustedes; porque ella ha sido protectora de muchos y de mí mismo."),
 "hch19_8": ("Hch 19:8–10", 6, "⁸ Entrando en la sinagoga, habló con valentía por tres meses, discutiendo y persuadiendo acerca del reino de Dios. ⁹ Pero como algunos se endurecían y no creían, hablando mal del Camino delante de la multitud, se apartó de ellos y separó a los discípulos, discutiendo cada día en la escuela de Tirano. ¹⁰ Esto continuó por dos años, de manera que todos los que habitaban en Asia, judíos y griegos, oyeron la palabra del Señor."),
 "hch19_19": ("Hch 19:18–20", 6, "¹⁸ Y muchos de los que habían creído venían confesando y dando cuenta de sus prácticas. ¹⁹ Y muchos de los que habían practicado la magia trajeron los libros y los quemaron delante de todos; y calculado su precio, hallaron que era cincuenta mil piezas de plata. ²⁰ Así crecía y prevalecía poderosamente la palabra del Señor."),
 "col4_13": ("Col 4:12–13", 6, "¹² Los saluda Epafras, que es uno de ustedes, siervo de Cristo Jesús, siempre luchando por ustedes en sus oraciones, para que estén firmes, perfectos y plenamente seguros en toda la voluntad de Dios. ¹³ Porque de él doy testimonio de que tiene gran solicitud por ustedes, por los de Laodicea y por los de Hierápolis."),
 "1co15_3": ("1 Co 15:3–5", 6, "³ Porque les transmití en primer lugar lo que también recibí: que Cristo murió por nuestros pecados según las Escrituras, ⁴ y que fue sepultado, y que resucitó al tercer día según las Escrituras, ⁵ y que se apareció a Cefas, y después a los doce."),
 "1co13_13": ("1 Co 13:13", 6, "Y ahora permanecen la fe, la esperanza y el amor, estos tres; pero el mayor de ellos es el amor."),
 "1co16_8": ("1 Co 16:8–9", 6, "⁸ Pero me quedaré en Éfeso hasta Pentecostés, ⁹ porque se me ha abierto una puerta grande y eficaz, y muchos son los adversarios."),
 "hch19_26": ("Hch 19:25–27", 6, "²⁵ A los cuales, reunidos con los obreros del mismo oficio, dijo: «Varones, saben que de este oficio obtenemos nuestra riqueza; ²⁶ y ven y oyen que este Pablo, no solo en Éfeso sino en casi toda Asia, ha apartado a muchas gentes con persuasión, diciendo que no son dioses los que se hacen con las manos. ²⁷ Y no solamente hay peligro de que este negocio nuestro venga a desacreditarse, sino también que el templo de la gran diosa Artemisa sea estimado en nada, y comience a ser destruida la majestad de aquella a quien venera toda Asia y el mundo»."),
 "hch19_34": ("Hch 19:34", 6, "Pero cuando supieron que era judío, todos a una voz gritaron casi por dos horas: «¡Grande es Artemisa de los efesios!»."),
 "2co1_8": ("2 Co 1:8–9", 6, "⁸ Porque no queremos, hermanos, que ignoren acerca de nuestra tribulación que nos sobrevino en Asia: que fuimos abrumados sobremanera, más allá de nuestras fuerzas, de tal modo que aun perdimos la esperanza de vivir. ⁹ Pero tuvimos en nosotros mismos sentencia de muerte, para que no confiáramos en nosotros mismos, sino en Dios que resucita a los muertos."),
 "2co4_7": ("2 Co 4:7–10", 6, "⁷ Pero tenemos este tesoro en vasos de barro, para que la excelencia del poder sea de Dios y no de nosotros: ⁸ atribulados en todo, pero no angustiados; en apuros, pero no desesperados; ⁹ perseguidos, pero no desamparados; derribados, pero no destruidos; ¹⁰ llevando siempre en el cuerpo la muerte de Jesús, para que también la vida de Jesús se manifieste en nuestro cuerpo."),
 "2co12_9": ("2 Co 12:9–10", 6, "⁹ Y me ha dicho: «Te basta mi gracia, porque el poder se perfecciona en la debilidad». Por tanto, de buena gana me gloriaré más bien en mis debilidades, para que repose sobre mí el poder de Cristo. ¹⁰ Por lo cual me complazco en las debilidades, en afrentas, en necesidades, en persecuciones, en angustias por Cristo; porque cuando soy débil, entonces soy fuerte."),
 "2co11_24": ("2 Co 11:23–25", 6, "²³ ¿Son ministros de Cristo? Como fuera de mí hablo: yo más; en trabajos más abundante, en cárceles más, en azotes sin número, en peligros de muerte muchas veces. ²⁴ De los judíos cinco veces he recibido cuarenta azotes menos uno; ²⁵ tres veces he sido azotado con varas; una vez apedreado; tres veces he padecido naufragio; una noche y un día he estado en lo profundo del mar."),
 "2co11_28": ("2 Co 11:26–28", 6, "²⁶ En caminos muchas veces; en peligros de ríos, peligros de salteadores, peligros de los de mi nación, peligros de los de las naciones, peligros en la ciudad, peligros en el desierto, peligros en el mar, peligros entre falsos hermanos; ²⁷ en trabajo y fatiga, en desvelos muchas veces, en hambre y sed, en ayunos muchas veces, en frío y desnudez; ²⁸ y además de lo exterior, lo que sobre mí se agolpa cada día: la preocupación por todas las iglesias."),
 "2co8_1": ("2 Co 8:1–4", 6, "¹ Les hacemos saber, hermanos, la gracia de Dios que se ha dado a las iglesias de Macedonia: ² que en gran prueba de tribulación, la abundancia de su gozo y su profunda pobreza abundaron en riquezas de su generosidad. ³ Pues doy testimonio de que según sus fuerzas, y aun más allá de sus fuerzas, de propia voluntad, ⁴ nos pidieron con muchos ruegos la gracia de participar en el servicio a los santos."),
 "ro1_16": ("Ro 1:16–17", 6, "¹⁶ Porque no me avergüenzo del evangelio, pues es poder de Dios para salvación a todo el que cree: al judío primero, y también al griego. ¹⁷ Porque en él la justicia de Dios se revela por fe y para fe, como está escrito: «Mas el justo por la fe vivirá»."),
 "ro15_24": ("Ro 15:23–24.28", 6, "²³ Pero ahora, no teniendo ya más campo en estas regiones, y deseando desde hace muchos años ir a ustedes, ²⁴ cuando vaya a España iré a ustedes; porque espero verlos al pasar y ser encaminado allá por ustedes, una vez que haya disfrutado de su compañía. ²⁸ Así que, cuando haya concluido esto y les haya entregado este fruto, pasaré entre ustedes rumbo a España."),
 "hch20_7": ("Hch 20:7–10", 6, "⁷ El primer día de la semana, reunidos nosotros para partir el pan, Pablo les enseñaba, habiendo de salir al día siguiente; y alargó el discurso hasta la medianoche. ⁸ Había muchas lámparas en el aposento alto donde estábamos reunidos. ⁹ Un joven llamado Eutico, sentado en la ventana, rendido de un sueño profundo mientras Pablo hablaba largamente, vencido del sueño cayó del tercer piso abajo, y lo levantaron muerto. ¹⁰ Pablo bajó, se echó sobre él y, abrazándolo, dijo: «No se alarmen, porque su vida está en él»."),
 "hch20_4": ("Hch 20:4–5", 6, "⁴ Lo acompañaron Sópater de Berea, hijo de Pirro; de los tesalonicenses, Aristarco y Segundo; Gayo de Derbe y Timoteo; y de Asia, Tíquico y Trófimo. ⁵ Éstos, adelantándose, nos esperaron en Troas."),
 "hch20_13": ("Hch 20:13–14", 0, "¹³ Nosotros, adelantándonos a embarcar, navegamos a Asón para recoger allí a Pablo, pues así lo había determinado, queriendo él ir por tierra. ¹⁴ Cuando se reunió con nosotros en Asón, lo tomamos a bordo y fuimos a Mitilene."),
 "hch20_24": ("Hch 20:22–24", 6, "²² Y ahora, he aquí, atado yo en espíritu, voy a Jerusalén, sin saber lo que allá me ha de acontecer; ²³ salvo que el Espíritu Santo por todas las ciudades me da testimonio de que me esperan cadenas y tribulaciones. ²⁴ Pero de ninguna cosa hago caso, ni tengo mi vida por preciosa para mí mismo, con tal de que acabe mi carrera y el ministerio que recibí del Señor Jesús: dar testimonio del evangelio de la gracia de Dios."),
 "hch20_28": ("Hch 20:28–29", 6, "²⁸ Mirad por ustedes y por todo el rebaño en que el Espíritu Santo los ha puesto por obispos, para pastorear la iglesia de Dios, que él adquirió con su propia sangre. ²⁹ Yo sé que después de mi partida entrarán entre ustedes lobos rapaces que no perdonarán al rebaño."),
 "hch20_35": ("Hch 20:35–38", 6, "³⁵ En todo les he enseñado que, trabajando así, se debe ayudar a los débiles, y recordar las palabras del Señor Jesús, que dijo: «Más bienaventurado es dar que recibir». ³⁶ Dicho esto, se puso de rodillas y oró con todos ellos. ³⁷ Hubo gran llanto de todos, y echándose al cuello de Pablo lo besaban, ³⁸ doliéndose sobre todo por la palabra que dijo: que no verían más su rostro. Y lo acompañaron al barco."),
 "hch21_4": ("Hch 21:3–4", 6, "³ Avistamos Chipre, la dejamos a la izquierda, navegamos a Siria y arribamos a Tiro, porque el barco había de descargar allí. ⁴ Hallados los discípulos, nos quedamos allí siete días; y ellos decían a Pablo por el Espíritu que no subiera a Jerusalén."),
 "hch21_11": ("Hch 21:10–11", 6, "¹⁰ Y deteniéndonos allí varios días, descendió de Judea un profeta llamado Agabo, ¹¹ quien, viniendo a vernos, tomó el cinto de Pablo, se ató los pies y las manos y dijo: «Esto dice el Espíritu Santo: Así atarán los judíos en Jerusalén al varón de quien es este cinto, y lo entregarán en manos de las naciones»."),
 "hch21_14": ("Hch 21:13–14", 6, "¹³ Entonces Pablo respondió: «¿Qué hacen llorando y quebrantándome el corazón? Porque yo estoy dispuesto no solo a ser atado, sino también a morir en Jerusalén por el nombre del Señor Jesús». ¹⁴ Como no lo pudimos persuadir, desistimos, diciendo: «Hágase la voluntad del Señor»."),
 "hch21_28": ("Hch 21:27–28", 7, "²⁷ Cuando estaban para cumplirse los siete días, los judíos de Asia, al verlo en el templo, alborotaron a toda la multitud y le echaron mano, ²⁸ gritando: «¡Varones israelitas, ayuden! Éste es el hombre que por todas partes enseña a todos contra el pueblo, la ley y este lugar; y además ha metido a griegos en el templo y ha profanado este santo lugar»."),
 "hch22_21": ("Hch 22:21–22", 7, "²¹ Y me dijo: «Ve, porque yo te enviaré lejos, a las naciones». ²² Y lo oyeron hasta esta palabra; entonces alzaron la voz diciendo: «¡Quita de la tierra a tal hombre, porque no conviene que viva!»."),
 "hch23_6": ("Hch 23:6", 7, "Entonces Pablo, sabiendo que una parte era de saduceos y la otra de fariseos, alzó la voz en el Sanedrín: «Varones hermanos, yo soy fariseo, hijo de fariseos; acerca de la esperanza y de la resurrección de los muertos se me juzga»."),
 "hch23_11": ("Hch 23:11", 7, "A la noche siguiente se le presentó el Señor y le dijo: «Ten ánimo, porque como has testificado de mí en Jerusalén, así es necesario que testifiques también en Roma»."),
 "hch23_16": ("Hch 23:16–17", 7, "¹⁶ Pero el hijo de la hermana de Pablo, oyendo hablar de la emboscada, fue y entró en la fortaleza y avisó a Pablo. ¹⁷ Pablo, llamando a uno de los centuriones, dijo: «Lleva a este joven ante el tribuno, porque tiene algo que informarle»."),
 "hch24_5": ("Hch 24:5–6", 7, "⁵ Porque hemos hallado que este hombre es una plaga, promotor de sediciones entre todos los judíos por toda la tierra habitada, y cabecilla de la secta de los nazarenos; ⁶ quien intentó también profanar el templo; y lo prendimos."),
 "hch24_25": ("Hch 24:24–26", 7, "²⁴ Algunos días después, viniendo Félix con Drusila su mujer, que era judía, llamó a Pablo y lo oyó acerca de la fe en Cristo Jesús. ²⁵ Pero al disertar Pablo acerca de la justicia, del dominio propio y del juicio venidero, Félix se espantó y dijo: «Ahora vete; cuando tenga oportunidad te llamaré». ²⁶ Esperaba también que Pablo le diera dinero; por eso lo hacía venir con frecuencia y conversaba con él."),
 "hch25_11": ("Hch 25:10–12", 7, "¹⁰ Pablo dijo: «Ante el tribunal del César estoy, donde debo ser juzgado. A los judíos no les he hecho ningún agravio, como tú sabes muy bien. ¹¹ Si algún agravio o cosa digna de muerte he hecho, no rehúso morir; pero si nada hay de las cosas de que éstos me acusan, nadie puede entregarme a ellos. Al César apelo». ¹² Entonces Festo, habiendo hablado con el consejo, respondió: «Al César has apelado; al César irás»."),
 "hch26_32": ("Hch 26:31–32", 7, "³¹ Y retirándose aparte, hablaban entre sí diciendo: «Nada digno de muerte ni de prisión ha hecho este hombre». ³² Y Agripa dijo a Festo: «Podía ser puesto en libertad este hombre, si no hubiera apelado al César»."),
 "hch26_16": ("Hch 26:16–18", 7, "¹⁶ Pero levántate y ponte sobre tus pies; porque para esto me he aparecido a ti: para ponerte por ministro y testigo de las cosas que has visto y de aquellas en que me apareceré a ti, ¹⁷ librándote de tu pueblo y de las naciones, a las cuales yo te envío ¹⁸ para que abras sus ojos, para que se conviertan de las tinieblas a la luz y del poder de Satanás a Dios; para que reciban perdón de pecados y herencia entre los santificados por la fe que es en mí."),
 "hch26_28": ("Hch 26:28–29", 7, "²⁸ Entonces Agripa dijo a Pablo: «Por poco me persuades a hacerme cristiano». ²⁹ Y Pablo dijo: «¡Quisiera Dios que por poco o por mucho, no solo tú sino también todos los que hoy me oyen fueran tales como yo soy, salvo estas cadenas!»."),
 "hch27_1": ("Hch 27:1–2", 8, "¹ Cuando se decidió que habíamos de navegar a Italia, entregaron a Pablo y a algunos otros presos a un centurión llamado Julio, de la cohorte Augusta. ² Y embarcándonos en una nave adramitena que iba a tocar los puertos de Asia, zarpamos, estando con nosotros Aristarco, macedonio de Tesalónica."),
 "hch27_6": ("Hch 27:5–6", 0, "⁵ Habiendo atravesado el mar frente a Cilicia y Panfilia, arribamos a Mira de Licia. ⁶ Y hallando allí el centurión una nave alejandrina que zarpaba para Italia, nos embarcó en ella."),
 "hch27_9": ("Hch 27:9–10", 8, "⁹ Pasado mucho tiempo, y siendo ya peligrosa la navegación por haber pasado ya el Ayuno, Pablo los amonestaba ¹⁰ diciéndoles: «Varones, veo que la navegación va a ser con perjuicio y mucha pérdida, no solo del cargamento y de la nave, sino también de nuestras vidas»."),
 "hch27_12": ("Hch 27:12", 8, "Y como el puerto no era cómodo para invernar, la mayoría acordó zarpar también de allí, por si pudieran arribar a Fenice, puerto de Creta que mira al suroeste y al noroeste, e invernar allí."),
 "hch27_14": ("Hch 27:14–17", 8, "¹⁴ Pero no mucho después dio contra la nave un viento huracanado llamado Euroaquilón. ¹⁵ Y siendo arrebatada la nave y no pudiendo poner proa al viento, nos abandonamos a él y nos dejamos llevar. ¹⁶ Y habiendo corrido a sotavento de una pequeña isla llamada Cauda, con dificultad pudimos sujetar el esquife; ¹⁷ y una vez subido a bordo, usaron de refuerzos para ceñir la nave; y teniendo temor de dar en la Sirte, arriaron las velas y quedaron a la deriva."),
 "hch27_22": ("Hch 27:22–25", 8, "²² Pero ahora los exhorto a tener buen ánimo, pues no habrá ninguna pérdida de vida entre ustedes, sino solamente de la nave. ²³ Porque esta noche ha estado conmigo el ángel del Dios de quien soy y a quien sirvo, ²⁴ diciendo: «Pablo, no temas; es necesario que comparezcas ante el César; y he aquí, Dios te ha concedido todos los que navegan contigo». ²⁵ Por tanto, oh varones, tengan buen ánimo; porque yo confío en Dios que será así como se me ha dicho."),
 "hch27_41": ("Hch 27:41–44", 8, "⁴¹ Pero dando en un lugar de dos aguas, hicieron encallar la nave; y la proa, hincada, quedó inmóvil, y la popa se abría con la violencia de las olas. ⁴² Los soldados acordaron matar a los presos, para que ninguno se fugara nadando. ⁴³ Pero el centurión, queriendo salvar a Pablo, les impidió este intento, y mandó que los que pudieran nadar se echaran los primeros y salieran a tierra, ⁴⁴ y los demás, parte en tablas, parte en cosas de la nave. Y así aconteció que todos se salvaron saliendo a tierra."),
 "hch28_2": ("Hch 28:1–3", 8, "¹ Estando ya a salvo, supimos que la isla se llamaba Malta. ² Y los bárbaros nos mostraron no poca humanidad; porque encendiendo un fuego, nos recibieron a todos a causa de la lluvia que caía y del frío. ³ Entonces, habiendo recogido Pablo algunas ramas secas, las echó al fuego; y una víbora, huyendo del calor, se le prendió en la mano."),
 "hch28_7": ("Hch 28:7–9", 8, "⁷ En aquellos lugares había propiedades del primero de la isla, llamado Publio, quien nos recibió y hospedó amistosamente tres días. ⁸ Y aconteció que el padre de Publio estaba en cama, enfermo de fiebre y de disentería; Pablo entró a verlo, oró, le impuso las manos y lo sanó. ⁹ Hecho esto, también los otros que en la isla tenían enfermedades venían y eran sanados."),
 "hch28_14": ("Hch 28:11–14", 8, "¹¹ Pasados tres meses, nos hicimos a la vela en una nave alejandrina que había invernado en la isla, la cual tenía por enseña a los Dióscuros. ¹² Y llegados a Siracusa, estuvimos allí tres días. ¹³ De allí, costeando, vinimos a Regio; y al otro día, soplando el viento sur, llegamos al segundo día a Puteoli, ¹⁴ donde habiendo hallado hermanos, nos rogaron que nos quedáramos con ellos siete días; y así llegamos a Roma."),
 "hch28_15": ("Hch 28:15", 8, "De allí, oyendo de nosotros los hermanos, salieron a recibirnos hasta el Foro de Apio y las Tres Tabernas; y al verlos, Pablo dio gracias a Dios y cobró aliento."),
 "hch28_16": ("Hch 28:16", 8, "Cuando llegamos a Roma, se le permitió a Pablo vivir aparte, con un soldado que lo custodiara."),
 "hch28_30": ("Hch 28:30–31", 8, "³⁰ Y Pablo permaneció dos años enteros en una casa alquilada, y recibía a todos los que venían a él, ³¹ predicando el reino de Dios y enseñando acerca del Señor Jesucristo con toda libertad, sin impedimento."),
 "fil1_21": ("Fil 1:21–23", 8, "²¹ Porque para mí el vivir es Cristo, y el morir es ganancia. ²² Pero si el vivir en la carne resulta para mí en fruto de trabajo, no sé entonces qué escoger. ²³ Porque de ambas cosas estoy puesto en estrecho, teniendo deseo de partir y estar con Cristo, lo cual es muchísimo mejor."),
 "flm10": ("Flm 10–11", 8, "¹⁰ Te ruego por mi hijo Onésimo, a quien engendré en mis prisiones, ¹¹ el cual en otro tiempo te fue inútil, pero ahora a ti y a mí nos es útil."),
 "ef3_1": ("Ef 3:1", 8, "Por esta causa yo, Pablo, prisionero de Cristo Jesús por ustedes, los de las naciones…"),
 "col4_10": ("Col 4:10–11", 8, "¹⁰ Los saluda Aristarco, mi compañero de prisiones, y Marcos, el primo de Bernabé —acerca del cual recibieron instrucciones: si va a ustedes, recíbanlo—, ¹¹ y Jesús, llamado Justo; éstos, que son de la circuncisión, son los únicos que me ayudan en el reino de Dios y me han sido un consuelo."),
 "tit1_5": ("Tit 1:5", 9, "Por esta causa te dejé en Creta: para que corrigieras lo deficiente y establecieras ancianos en cada ciudad, como yo te mandé."),
 "tit3_12": ("Tit 3:12", 9, "Cuando envíe a ti a Artemas o a Tíquico, apresúrate a venir a mí en Nicópolis, porque allí he determinado pasar el invierno."),
 "1ti1_3": ("1 Ti 1:3", 9, "Como te rogué que te quedaras en Éfeso cuando fui a Macedonia, para que mandaras a algunos que no enseñen diferente doctrina…"),
 "1ti1_15": ("1 Ti 1:15–16", 9, "¹⁵ Palabra fiel y digna de ser recibida por todos: que Cristo Jesús vino al mundo para salvar a los pecadores, de los cuales yo soy el primero. ¹⁶ Pero por esto fui recibido a misericordia: para que Jesucristo mostrara en mí, el primero, toda su paciencia, como ejemplo de los que habrían de creer en él para vida eterna."),
 "1ti3_15": ("1 Ti 3:15", 9, "Para que, si tardo, sepas cómo debes conducirte en la casa de Dios, que es la iglesia del Dios vivo, columna y baluarte de la verdad."),
 "tit1_12": ("Tit 1:12–13", 9, "¹² Uno de ellos, su propio profeta, dijo: «Los cretenses, siempre mentirosos, malas bestias, vientres ociosos». ¹³ Este testimonio es verdadero; por tanto, repréndelos duramente, para que sean sanos en la fe."),
 "2ti4_7": ("2 Ti 4:6–8", 9, "⁶ Porque yo ya estoy para ser ofrecido en libación, y el tiempo de mi partida está cerca. ⁷ He peleado la buena batalla, he acabado la carrera, he guardado la fe. ⁸ Por lo demás, me está reservada la corona de justicia, que me dará el Señor, juez justo, en aquel día; y no solo a mí, sino también a todos los que aman su venida."),
 "2ti4_13": ("2 Ti 4:9–13", 9, "⁹ Procura venir pronto a mí, ¹⁰ porque Demas me ha desamparado, amando este mundo, y se ha ido a Tesalónica; Crescente a Galacia, y Tito a Dalmacia. ¹¹ Solo Lucas está conmigo. Toma a Marcos y tráelo contigo, porque me es útil para el ministerio. ¹² A Tíquico lo envié a Éfeso. ¹³ Trae, cuando vengas, la capa que dejé en Troas en casa de Carpo, y los libros, sobre todo los pergaminos."),
 "2ti4_16": ("2 Ti 4:16–18", 9, "¹⁶ En mi primera defensa nadie estuvo a mi lado, sino que todos me desampararon; no les sea tomado en cuenta. ¹⁷ Pero el Señor estuvo a mi lado y me dio fuerzas, para que por mí fuera cumplida la predicación y la oyeran todas las naciones; y fui librado de la boca del león. ¹⁸ El Señor me librará de toda obra mala y me preservará para su reino celestial. A él sea la gloria por los siglos de los siglos. Amén."),
 "2ti1_16": ("2 Ti 1:16–17", 9, "¹⁶ Tenga el Señor misericordia de la casa de Onesíforo, porque muchas veces me confortó y no se avergonzó de mis cadenas, ¹⁷ sino que, cuando estuvo en Roma, me buscó con diligencia y me halló."),
 "ef3_8": ("Ef 3:8", 9, "A mí, el menor de todos los santos, me fue dada esta gracia: anunciar entre las naciones el evangelio de las inescrutables riquezas de Cristo."),
 "ga2_20": ("Gá 2:19–20", 9, "¹⁹ Porque yo por la ley soy muerto para la ley, a fin de vivir para Dios. Con Cristo estoy juntamente crucificado; ²⁰ y ya no vivo yo, sino que Cristo vive en mí; y lo que ahora vivo en la carne, lo vivo en la fe del Hijo de Dios, que me amó y se entregó a sí mismo por mí."),
 "is49_6": ("Is 49:6", 3, "Y dijo: «Poco es que seas mi siervo para levantar las tribus de Jacob y restaurar a los preservados de Israel: te he puesto por luz de las naciones, para que mi salvación llegue hasta el extremo de la tierra»."),
}
HEBREO = {"Gn", "Ex", "Lv", "Nm", "Dt", "Jos", "Jue", "1 S", "1 R", "2 R", "Sal", "Is", "Jer", "Os", "Mi"}

ORIG = {"hch7_58": ["Hch 7:58–60", "Hch 8:1"]}   # citas que cruzan capítulo: se leen por partes

def refs_biblicas():
    R = {}
    for k, (lab, era, tr) in P.items():
        lib = lab.rsplit(" ", 1)[0]
        citas = ORIG.get(k) or [lab.split(";")[0].strip()]
        if lib in HEBREO:
            R[k] = {"label": lab, "era": era, "he": " ".join(T.he(c) for c in citas), "tr": tr, "lang": "he"}
        else:
            R[k] = {"label": lab, "era": era, "he": "\n".join(T.gr(c) for c in citas), "tr": tr, "lang": "el"}
    return R

